import { ObstacleBadge } from '@apps/Obstacles/components/ObstacleBadge';

import { IBaseArticle } from '../@types/articles.types';

interface IArticleListItemProps {
  article: IBaseArticle;
}

const ArticleListItem = ({ article }: IArticleListItemProps) => {
  return (
    <div className="d-flex">
      {article.name}{' '}
      {article.obstacle && (
        <span className="ms-auto" title={article.obstacle.name}>
          <ObstacleBadge obstacle={article.obstacle} />
        </span>
      )}
    </div>
  );
};

export default ArticleListItem;
